            return f'{mask}!*@*'
        if re.match('^[^@!]+$', mask) is not None:
            return f'*!*@{mask}'
        m = re.match('^([^!@]+)@$', mask)
        if m is not None:
            return f'*!{m.group(1)}@*'
        m = re.match('^([^!@]+)@([^@!]+)$', mask)
        if m is not None:
            return f'*!{m.group(1)}@{m.group(2)}'
        m = re.match('^([^!@]+)!(^[!@]+)@?$', mask)
        if m is not None:
            return f'{m.group(1)}!{m.group(2)}@*'
        return ''
    return None
