            if count:
                if option_value is not None:
                    options[option] = options.get(option, "") + option_value
            else:
                options[option] = option_value
            rest = rest[optmatch.end() :]
        result.append(options)
        return tuple(result)
    return tuple(result) if result else ("", {})

