                format = EXTENSION[ext]
            except KeyError:
                init()
                try:
                    format = EXTENSION[ext]
                except KeyError:
                    raise KeyError(ext)
        try:
            save_handler = SAVE[format.upper()]
        except KeyError:
            init()
            save_handler = SAVE[format.upper()]
        if isPath(fp):
            fp = builtins.open(fp, "wb")
            close = 1
        else:
            close = 0
        try:
            save_handler(self, fp, filename)
        finally:
            if close:
                fp.close()
