                                autologin_as, remote_address
                            )
                        )
                        flask.session["login_mechanism"] = "autologin"
                        return autologin_user
            except Exception:
                logger.exception(
                    "Could not autologin user {} from {} for networks {}".format(
                        autologin_as, remote_address, local_networks
                    )
                )
