        if os.path.isfile(target_path) or os.path.isdir(target_path):
            new_path = find_unique_duplicate_filepath(target_path)
            try:
                if os.path.isfile(target_path):
                    copytree(target_path, new_path)
                else:
                    copytree(target_path, new_path, use_gitignore=False)
            except Exception as e:
                app.logger.error(e)
                return jsonify({"message": "Copy of file/directory failed"}), 500
        else:
            return jsonify({"message": "No file or directory at path %s" % path}), 500
        return jsonify({"message": "Success"})
    @app.route("/async/file-management/create-dir", methods=["POST"])
    def filemanager_create_dir():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        path = "/".join(path.split("/")[1:])
        full_path = safe_join(root_dir_path, path)
        if os.path.isdir(full_path) or os.path.isfile(full_path):
            return jsonify({"message": "Path already exists"}), 500
        os.makedirs(full_path, exist_ok=True)
        return jsonify({"message": "Success"})
    @app.route("/async/file-management/upload", methods=["POST"])
    def filemanager_upload():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        app.logger.debug(path)
        if "file" not in request.files or request.files["file"].filename == "":
            return jsonify({"message": "No file found"}), 500
        file = request.files["file"]
        if file and allowed_file(file.filename):
            filename = file.filename.split(os.sep)[-1]
            path = path[1:]
            dir_path = safe_join(root_dir_path, path)
            if not os.path.isdir(dir_path):
                os.makedirs(dir_path, exist_ok=True)
            file_path = safe_join(dir_path, filename)
            file.save(file_path)
        return jsonify({"file_path": file_path})
    @app.route("/async/file-management/rename", methods=["POST"])
    def filemanager_rename():
        old_path = request.args.get("old_path")
        new_path = request.args.get("new_path")
        old_root = request.args.get("old_root")
        new_root = request.args.get("new_root")
        project_uuid = request.args.get("project_uuid")
        try:
            old_root_path, _ = process_request(
                root=old_root, path=new_path, project_uuid=project_uuid
            )
            new_root_path, _ = process_request(
                root=new_root, path=new_path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        abs_old_path = safe_join(old_root_path, old_path[1:])
        abs_new_path = safe_join(new_root_path, new_path[1:])
        try:
            os.rename(abs_old_path, abs_new_path)
            return jsonify({"message": "Success"})
        except Exception:
            return jsonify({"message": "Failed to rename"}), 500
    @app.route("/async/file-management/download", methods=["GET"])
    def filemanager_download():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        target_path = safe_join(root_dir_path, path[1:])
        if os.path.isfile(target_path):
            return send_file(target_path, as_attachment=True)
        else:
            memory_file = io.BytesIO()
            with zipfile.ZipFile(memory_file, "w", zipfile.ZIP_STORED) as zf:
                zipdir(target_path, zf)
            memory_file.seek(0)
            return send_file(
                memory_file,
                mimetype="application/zip",
                as_attachment=True,
                attachment_filename=os.path.basename(target_path[:-1]) + ".zip",
            )
    @app.route("/async/file-management/extension-search", methods=["GET"])
    def filemanager_extension_search():
        root = request.args.get("root")
        path = request.args.get("path")
        project_uuid = request.args.get("project_uuid")
        extensions = request.args.get("extensions")
        try:
            root_dir_path, _ = process_request(
                root=root, path=path, project_uuid=project_uuid
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        if extensions is None:
            return jsonify({"message": "extensions is required."}), 400
        path_filter = path
        extensions = extensions.split(",")
        path_filter = path_filter[1:]
        app.logger.info(f"Path filter {path_filter}")
        matches = []
        for extension in extensions:
            matches += list(
                pathlib.Path(safe_join(root_dir_path, path_filter)).glob(
                    "**/*.{}".format(extension)
                )
            )
        return jsonify(
            {"files": [os.path.relpath(str(match), root_dir_path) for match in matches]}
        )
    @app.route("/async/file-management/browse", methods=["GET"])
    def browse_files():
        root = request.args.get("root")
        path = request.args.get("path")
        depth_as_string = request.args.get("depth")
        project_uuid = request.args.get("project_uuid")
        try:
            root_dir_path, depth = process_request(
                root=root,
                path=path,
                project_uuid=project_uuid,
                depth=depth_as_string,
                is_path_required=False,
            )
        except Exception as e:
            return jsonify({"message": str(e)}), 400
        path_filter = path if path else "/"
        app.logger.info(f"Path filter {path_filter}")
        return jsonify(
            generate_tree(root_dir_path, path_filter=path_filter, depth=depth)
        )

class WardenRule:
    async def do_actions(self, *, cog: MixinMeta, user: discord.Member=None, message: discord.Message=None,
                         guild: discord.Guild=None, debug=False):
        if message and not user:
            user = message.author
        guild = guild if guild else user.guild
        channel: discord.Channel = message.channel if message else None
        templates_vars = {}
        await populate_ctx_vars(t_vars=templates_vars,
                                rule=self,
                                cog=cog,
                                guild=guild,
                                message=message,
                                user=user,
                                channel=channel,
                                debug=debug)
        def safe_sub(string):
            if string == discord.Embed.Empty:
                return string
            return Template(string).safe_substitute(templates_vars)
        last_sent_message: Optional[discord.Message] = None
        last_expel_action = None
        processors = {}
        def processor(action: Action, suggest: Action=None):
            def decorator(function):
                def wrapper(*args, **kwargs):
                    if suggest is not None:
                        cog.send_to_monitor(guild, f"[Warden] ({self.name}): Action "
                                                   f"'{action.value}' is deprecated, use "
                                                   f"'{suggest.value}' instead.")
                    return function(*args, **kwargs)
                processors[action] = wrapper
                return wrapper
            return decorator
        @processor(Action.DeleteUserMessage)
        async def delete_user_message(params: models.IsNone):
            await message.delete()
        @processor(Action.Dm, suggest=Action.SendMessage)
        async def send_dm(params: models.SendMessageToUser):
            nonlocal last_sent_message
            user_to_dm = guild.get_member(params.id)
            if not user_to_dm:
                user_to_dm = discord.utils.get(guild.members, name=params.id)
            if not user_to_dm:
                return
            content = Template(params.content).safe_substitute(templates_vars)
            try:
                last_sent_message = await user_to_dm.send(content)
            except:
                cog.send_to_monitor(guild, f"[Warden] ({self.name}): Failed to DM user "
                                    f"{user_to_dm} ({user_to_dm.id})")
                last_sent_message = None
        @processor(Action.DmUser, suggest=Action.SendMessage)
        async def send_user_dm(params: models.IsStr):
            nonlocal last_sent_message
            text = Template(params.value).safe_substitute(templates_vars)
            try:
                last_sent_message = await user.send(text)
            except:
                cog.send_to_monitor(guild, f"[Warden] ({self.name}): Failed to DM user "
                                    f"{user} ({user.id})")
                last_sent_message = None
        @processor(Action.NotifyStaff)
        async def notify_staff(params: models.NotifyStaff):
            nonlocal last_sent_message
            text_only = params.__fields_set__ == {"content"}
            quick_action = None
            if params.qa_target:
                if params.qa_reason is None:
                    params.qa_reason = ""
                params.qa_target = safe_sub(params.qa_target)
                params.qa_reason = safe_sub(params.qa_reason)
                try:
                    quick_action = QuickAction(int(params.qa_target), params.qa_reason)
                except ValueError:
                    raise ExecutionError(f"{params.qa_target} is not a valid ID for a Quick Action target.")
            jump_to_msg = None
            if params.jump_to_ctx_message:
                jump_to_msg = message
            if params.jump_to:
                params.jump_to.channel_id = safe_sub(params.jump_to.channel_id)
                params.jump_to.message_id = safe_sub(params.jump_to.message_id)
                try:
                    jump_to_ch = discord.utils.get(guild.text_channels, id=int(params.jump_to.channel_id))
                except ValueError:
                    raise ExecutionError(f"{params.jump_to.channel_id} is not a valid channel ID for a \"jump to\" message.")
                if not params.jump_to.message_id.isdigit():
                    raise ExecutionError(f"{params.jump_to.message_id} is not a valid message ID for a \"jump to\" message.")
                if jump_to_ch:
                    jump_to_msg = jump_to_ch.get_partial_message(params.jump_to.message_id)
                else:
                    raise ExecutionError(f"I could not find the destination channel for the \"jump to\" message.")
            title = safe_sub(params.title) if params.title else None
            heat_key = safe_sub(params.no_repeat_key) if params.no_repeat_key else None
            fields = []
            if params.fields:
                for param in params.fields:
                    fields.append(param.dict())
            for field in fields:
                for attr in ("name", "value"):
                    if attr in field:
                        field[attr] = safe_sub(field[attr])
            if params.add_ctx_fields:
                ctx_fields = []
                if user:
                    ctx_fields.append({"name": "Username", "value": f"`{user}`"})
                    ctx_fields.append({"name": "ID", "value": f"`{user.id}`"})
                if message:
                    ctx_fields.append({"name": "Channel", "value": message.channel.mention})
                fields = ctx_fields + fields
            footer = None
            if not text_only:
                if params.footer_text is None:
                    footer = f"Warden rule `{self.name}`"
                elif params.footer_text == "":
                    footer = None
                else:
                    footer = safe_sub(params.footer_text)
            last_sent_message = await cog.send_notification(guild,
                                                            safe_sub(params.content),
                                                            title=title,
                                                            ping=params.ping,
                                                            fields=fields,
                                                            footer=footer,
                                                            thumbnail=safe_sub(params.thumbnail) if params.thumbnail else None,
                                                            jump_to=jump_to_msg,
                                                            no_repeat_for=params.no_repeat_for,
                                                            heat_key=heat_key,
                                                            quick_action=quick_action,
                                                            force_text_only=text_only,
                                                            allow_everyone_ping=params.allow_everyone_ping)
