                    footer = f"Warden rule `{self.name}`"
                elif params.footer_text == "":
                    footer = None
                else:
                    footer = safe_sub(params.footer_text)
            last_sent_message = await cog.send_notification(guild,
                                                            safe_sub(params.content),
                                                            title=title,
                                                            ping=params.ping,
