class LoginHandler(JupyterHandler):
    def _redirect_safe(self, url, default=None):
        """Redirect if url is on our PATH
        Full-domain redirects are allowed if they pass our CORS origin checks.
        Otherwise use default (self.base_url if unspecified).
        """
        if default is None:
            default = self.base_url
        if not url.startswith(self.base_url):
            allow = False
            if '://' in url:
                parsed = urlparse(url.lower())
                origin = '%s://%s' % (parsed.scheme, parsed.netloc)
                if self.allow_origin:
                    allow = self.allow_origin == origin
                elif self.allow_origin_pat:
                    allow = bool(self.allow_origin_pat.match(origin))
            if not allow:
                self.log.warning("Not allowing login redirect to %r" % url)
                url = default
        self.redirect(url)
    def get(self):
            self._redirect_safe(next_url)
    def post(self):
        self._redirect_safe(next_url)

class LoginHandler(JupyterHandler):
    def _redirect_safe(self, url, default=None):
        """Redirect if url is on our PATH
        Full-domain redirects are allowed if they pass our CORS origin checks.
        Otherwise use default (self.base_url if unspecified).
        """
        if default is None:
            default = self.base_url
        url = url.replace("\\", "%5C")
        parsed = urlparse(url)
        if parsed.netloc or not (parsed.path + "/").startswith(self.base_url):
            allow = False
            if parsed.netloc:
                origin = '%s://%s' % (parsed.scheme, parsed.netloc)
                origin = origin.lower()
                if self.allow_origin:
                    allow = self.allow_origin == origin
                elif self.allow_origin_pat:
                    allow = bool(self.allow_origin_pat.match(origin))
            if not allow:
                self.log.warning("Not allowing login redirect to %r" % url)
                url = default
        self.redirect(url)
    def get(self):
            self._redirect_safe(next_url)
    def post(self):
        self._redirect_safe(next_url)

class check_user_or_serial_in_request(object):
    def __call__(self, func):
        @functools.wraps(func)
        def check_user_or_serial_in_request_wrapper(*args, **kwds):
            user = self.request.all_data.get("user")
            serial = self.request.all_data.get("serial")
            if not serial and not user:
                raise ParameterError(_("You need to specify a serial or a user."))
            f_result = func(*args, **kwds)
            return f_result
        return check_user_or_serial_in_request_wrapper

class check_user_or_serial_in_request(object):
    def __call__(self, func):
        @functools.wraps(func)
        def check_user_or_serial_in_request_wrapper(*args, **kwds):
            user = self.request.all_data.get("user", "").strip()
            serial = self.request.all_data.get("serial", "").strip()
            if not serial and not user:
                raise ParameterError(_("You need to specify a serial or a user."))
            if "*" in serial:
                raise ParameterError(_("Invalid serial number."))
            if "%" in user:
                raise ParameterError(_("Invalid user."))
            f_result = func(*args, **kwds)
            return f_result
        return check_user_or_serial_in_request_wrapper

